//${AOs::Priming::SM::active::Start_Priming::Stage_First} ....................
static QState Priming_Stage_First(Priming * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Priming::SM::active::Start_Priming::Stage_First}
        case Q_ENTRY_SIG: {
            ErigeEvt *pe1;
            pe1 = Q_NEW(ErigeEvt,SUCTION_STOP_SIG);
            QACTIVE_POST(AO_Suction,&pe1->super,NULL);
            me->Wdata->_state = PRIMING_STATE_STAGE_ONE;  //预充第一阶段
            me->_timcnt = 0;
            // me->Wdata->_primingRuntime = 48000;        //运行时间为48s
            me->Wdata->_primingRuntime = 53000;        //运行时间为53s
            Infusion_Task_ValveCtl(1);    //打开管制
            bsp_suction_SourceCtl(PRIMING_SUCTION_FLOW);    //80cc抽液体
            QTimeEvt_armX(&me->_timEvt, 100, 100U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Priming::SM::active::Start_Priming::Stage_First}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = PRIMING_STATE_STAGE_ONE; //预充第一阶段
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Priming::SM::active::Start_Priming::Stage_First::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;
            Infusion_Task_ValveCtl(1);    //打开管制
            if(me->Wcof->_enBypass)    //使能了分流
            {
                me->Wdata->_primingRuntime = 21000- me->_timcnt*100;;    //使能分流后时间变成21s
            }
            else
            {
                // me->Wdata->_primingRuntime = 48000 - me->_timcnt*100;
                me->Wdata->_primingRuntime = 53000 - me->_timcnt*100;
            }
            if((_Priming_Task_GetPressure())<-650)
            {
                bsp_suction_SourceCtl(0);    //抽吸停止
            }
            else
                bsp_suction_SourceCtl(PRIMING_SUCTION_FLOW);    //80cc抽液体
            //${AOs::Priming::SM::active::Start_Priming::Stage_First::TIMEOUT::[done]}
            if (me->Wdata->_primingRuntime <=17000) {
                //${AOs::Priming::SM::active::Start_Priming::Stage_First::TIMEOUT::[done]::[_Priming_Task_GetPressure()<=-6~}
                if (_Priming_Task_GetPressure() <=-600) {
                    me->Wdata->_errCode = PRIMING_SUCTION_VACCUM_HIGH;
                    bsp_error_list_add(me->Wdata->_errCode);
                    status_ = Q_TRAN(&Priming_IDEL);
                }
                //${AOs::Priming::SM::active::Start_Priming::Stage_First::TIMEOUT::[done]::[else]}
                else {
                    status_ = Q_TRAN(&Priming_Stage_Second);
                }
            }
            //${AOs::Priming::SM::active::Start_Priming::Stage_First::TIMEOUT::[else]}
            else {
                status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Priming_Start_Priming);
            break;
        }
    }
    return status_;
}

