static QState Priming_Start_Phaco_Test(Priming * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Priming::SM::active::Start_Phaco_Test}
        case Q_ENTRY_SIG: {
            ErigeEvt *pe1;
            pe1 = Q_NEW(ErigeEvt,SUCTION_STOP_SIG);
            QACTIVE_POST(AO_Suction,&pe1->super,NULL);
            me->Wdata->_state = PRIMING_STATE_STAGE_PHACO;
            me->_timcnt = 0;
            me->Wdata->_errCode = 0;
            me->Wdata->_primingRuntime =    15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest);        //运行时间为20s
            me->_phacopwr =  _Priming_Task_GetPhacoPow();    //获取超乳校准前的功率
            Infusion_Task_ValveCtl(1);    //打开灌注
            bsp_suction_SourceCtl(30);    //30cc进行抽吸
            QTimeEvt_armX(&me->_timEvt, 1000, 1000U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Priming::SM::active::Start_Phaco_Test}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = PRIMING_STATE_STAGE_PHACO;
            _Priming_Task_Phaco_Test(0,0);
            bsp_suction_SourceCtl(0);
            Infusion_Task_ValveCtl(0);    //关闭灌注
            Phaco_Task_SetScanState(-1);
						ramcof.phacocof._prams._ltim = 0;
            Phaco_Task_SetMode(PHACO_IDEL_MODE,ramcof.phacocof._prams);
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Priming::SM::active::Start_Phaco_Test::PRIMING_STOP}
        case PRIMING_STOP_SIG: {
            status_ = Q_TRAN(&Priming_IDEL);
            break;
        }
        //${AOs::Priming::SM::active::Start_Phaco_Test::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;
            me->Wdata->_primingRuntime = (15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest)) - (me->_timcnt*1000);
            bsp_suction_SourceCtl(30);    //30cc进行抽吸
            Infusion_Task_ValveCtl(1);    //打开灌注
            //${AOs::Priming::SM::active::Start_Phaco_Test::TIMEOUT::[me->Wdata->_primingRuntime==0]}
            if (me->Wdata->_primingRuntime == 0) {
                status_ = Q_TRAN(&Priming_IDEL);
            }
            else if (me->Wdata->_primingRuntime==(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-2000) //23S
            {
                // _Priming_Task_Phaco_Test(0,30); //提前预振一次
								ramcof.phacocof._prams._ltim = 20;
								Phaco_Task_SetScanState(-1);
                Phaco_Task_SetMode(PHACO_SCANFREQ_MODE,ramcof.phacocof._prams);
                status_ = Q_HANDLED();
            }
            //${AOs::Priming::SM::active::Start_Phaco_Test::TIMEOUT::[phaco_test]}
            else if (me->Wdata->_primingRuntime>=(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-10000 && me->Wdata->_primingRuntime<(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-7000) {

                if(me->Wdata->_primingRuntime ==(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-10000)    
                {
                    status_ = Q_HANDLED();
                }
                else
                    status_ = Q_HANDLED();
            }
            //${AOs::Priming::SM::active::Start_Phaco_Test::TIMEOUT::[me->Wdata->_primingRuntime>=700~}
            else if (me->Wdata->_primingRuntime>=(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-18000 && me->Wdata->_primingRuntime<(15000+_Priming_Task_Phaco_CalcRunTime(me->Wcof->_phacoTest))-20000) {
                
                if(me->Wcof->_phacoTest == PRIMING_PHACO_TEST_LONGITUDINALTRANSVERSE) //纵扭复合
                {
                    if (Phaco_Task_GetScanState() == 1) //扫频成功
                    {
                        status_ = Q_HANDLED();
                    }
                    else 
                    {
                        me->Wdata->_errCode = PRIMING_PHACO_TEST_FAIL1; // 扭振测试失败
                        bsp_error_list_add(me->Wdata->_errCode);
                        status_ = Q_TRAN(&Priming_IDEL);
                    }
               
                }
                else    //单纵或者单扭动
                {
                    status_ = Q_HANDLED();
                }
            }
            //${AOs::Priming::SM::active::Start_Phaco_Test::TIMEOUT::[else]}
            else {

                status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Priming_active);
            break;
        }
    }
    return status_;
}
//$enddef${AOs::Priming} ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
